<?php declare(strict_types=1); ?>
<div class="module-toolbar"><p class="module-intro">Personel kimlik, görev ve ücret bilgileri.</p><a class="btn secondary action-link" href="index.php?page=employees">← Liste</a></div><?php if($errors): ?><div class="alert"><?= kd_e(implode(' ',$errors)) ?></div><?php endif; ?><section class="panel customer-form-panel"><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="save"><input type="hidden" name="employee_id" value="<?= (int)$employee['id'] ?>"><div class="customer-fields"><label>Ad *<input name="first_name" required value="<?= kd_e($employee['first_name']) ?>"></label><label>Soyad *<input name="last_name" required value="<?= kd_e($employee['last_name']) ?>"></label><label>E-posta<input type="email" name="email" value="<?= kd_e($employee['email']) ?>"></label><label>Telefon<input name="phone" value="<?= kd_e($employee['phone']) ?>"></label><label>Departman<input name="department" value="<?= kd_e($employee['department_name']) ?>"></label><label>Pozisyon<input name="position" value="<?= kd_e($employee['position']) ?>"></label><label>İşe giriş tarihi<input type="date" name="hire_date" value="<?= kd_e($employee['hire_date']) ?>"></label><label>Durum<select name="employment_status"><option value="active" <?= $employee['employment_status']==='active'?'selected':'' ?>>Aktif</option><option value="inactive" <?= $employee['employment_status']==='inactive'?'selected':'' ?>>Pasif</option><option value="terminated" <?= $employee['employment_status']==='terminated'?'selected':'' ?>>İşten ayrıldı</option></select></label><label>Temel maaş<input type="number" name="base_salary" min="0" step=".01" value="<?= kd_e($employee['base_salary']) ?>"></label><label>Para birimi<select name="currency"><?php foreach(['TRY','USD','EUR','GBP'] as $cur): ?><option <?= $employee['currency']===$cur?'selected':'' ?>><?= $cur ?></option><?php endforeach; ?></select></label><label class="field-wide">Notlar<textarea name="notes"><?= kd_e($employee['notes']) ?></textarea></label></div><div class="form-actions"><button class="btn primary">Personel kaydını kaydet</button></div></form></section>
